BUG: `Interval.fromISO` in /luxon/src/interval.js does not work when `Settings.throwOnInvalid` is true, because `DateTime.fromISO(...)` throws (instead of returning an invalid DateTime) in that mode, so ISO interval strings that use a duration on one side (e.g. "2007-03-01T13:00:00/P1Y2M10DT2H30M" or "P1Y2M10DT2H30M/2008-05-11T15:30:00") throw instead of parsing. Also the final error message has a typo: `can't be parsed asISO 8601` should be `can't be parsed as ISO 8601`.

EDIT: In /luxon/src/interval.js, replace the whole body of `static fromISO(text, opts)` (currently lines 134-157) with exactly this implementation:

  static fromISO(text, opts) {
    const [s, e] = (text || "").split("/", 2);
    if (s && e) {
      let start, startIsValid;
      try {
        start = DateTime.fromISO(s, opts);
        startIsValid = start.isValid;
      } catch (e) {
        startIsValid = false;
      }

      let end, endIsValid;
      try {
        end = DateTime.fromISO(e, opts);
        endIsValid = end.isValid;
      } catch (e) {
        endIsValid = false;
      }

      if (startIsValid && endIsValid) {
        return Interval.fromDateTimes(start, end);
      }

      if (startIsValid) {
        const dur = Duration.fromISO(e, opts);
        if (dur.isValid) {
          return Interval.after(start, dur);
        }
      } else if (endIsValid) {
        const dur = Duration.fromISO(s, opts);
        if (dur.isValid) {
          return Interval.before(end, dur);
        }
      }
    }
    return Interval.invalid("unparsable", `the input "${text}" can't be parsed as ISO 8601`);
  }

